import {createRequire} from 'node:module';
import type {Redis} from 'ioredis';
import {createHash,randomUUID} from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import type {TaskQueue} from '../brain/task-queue.js';
import {resolveShadowCeoDataRoot,resolveShadowCeoAuthorityDir} from '../orchestration/shadow-ceo-integration/durable-paths.js';
const require=createRequire(import.meta.url);
type RecoveryAdapter = {
 captureRuntimeRecoverySet(args:Record<string,unknown>):Promise<Work8RecoveryResult>;
 verifyRuntimeRecoverySet(args:{directory:string;digest:string}):unknown;
 finalizeRuntimeRecoverySet(args:Work8RecoveryResult):Work8RecoveryResult;
};
export type Work8RecoveryRequest={destination:string;sourceCommit:string;frontendRevision:string;requireComplete?:boolean;captureRepositoryLifecycle?:boolean};
export type Work8RecoveryResult={directory:string;digest:string;manifest:{completeLiveState:false;bootAllowed:false;[key:string]:unknown}};
// Atomic database inventory includes pending jobs, sessions and TTLs; it does
// not establish exclusion of remote producers before or after this command.
const redisSnapshot=`
if redis.call('DBSIZE') > 10000 then return redis.error_reply('RECOVERY_REDIS_KEY_LIMIT') end
local clock = redis.call('TIME')
local capturedAt = tonumber(clock[1])*1000+math.floor(tonumber(clock[2])/1000)
local out = {}; local total = 0
for _, key in ipairs(redis.call('KEYS', '*')) do
 local dump = redis.call('DUMP', key); local ttl = redis.call('PTTL', key)
 if dump and ttl >= -1 then
  total = total + string.len(key) + string.len(dump)
  if total > 33554432 then return redis.error_reply('RECOVERY_REDIS_BYTE_LIMIT') end
  table.insert(out, {key, dump, ttl})
 end
end
return {capturedAt, out}`;
type RedisInventoryRow = {key:string;dump:string;ttl:number};
/** The server timestamp and PTTL values belong to one atomic snapshot, so client
 * queueing/network delays cannot shorten the original session lifetime. */
export async function captureRedisSnapshot(queue:TaskQueue):Promise<{capturedAt:number;rows:RedisInventoryRow[]}> {
 const client=await queue.queue.client;
 const binaryClient=client as unknown as {evalBuffer?:(script:string,keys:number)=>Promise<[number,Array<[Buffer,Buffer,number]>]>};
 if(typeof binaryClient.evalBuffer!=='function') throw new Error('REDIS_BINARY_SNAPSHOT_UNAVAILABLE');
 const [capturedAt,rows]=await binaryClient.evalBuffer(redisSnapshot,0);
 if(!Number.isSafeInteger(capturedAt)||capturedAt<=0)throw new Error('REDIS_SNAPSHOT_TIME_INVALID');
 return {capturedAt,rows:rows.map(([key,dump,ttl])=>({key:key.toString('base64'),dump:dump.toString('base64'),ttl})).sort((a,b)=>a.key.localeCompare(b.key))};
}
/** Preserve the established row-array API for inspection consumers. */
export async function captureRedisInventory(queue:TaskQueue) {
 return (await captureRedisSnapshot(queue)).rows;
}
export async function captureWork8RecoveryInventory(request:Work8RecoveryRequest,paths:{root:string;primaryPath:string;shadowPath:string},queue:TaskQueue):Promise<Work8RecoveryResult>{
 if(request.requireComplete!==false) throw new Error("FULL_RUNTIME_CAPTURE_UNPROVEN: Redis producers, watchdog, continuation and protected custody remain uncovered; only explicit scoped inspection is available");
 return (require('../../../deployment/work8-recovery-set.cjs') as RecoveryAdapter).captureRuntimeRecoverySet({...request,...paths,captureId:randomUUID(),captureRepositoryLifecycle:request.captureRepositoryLifecycle===true,captureObserverWatchdog:process.env.WORK8_SUPERVISED_OBSERVERS==='1',
  authorityFile:path.join(resolveShadowCeoAuthorityDir(),'authority-store.json'),
  requestOwnersFile:path.join(resolveShadowCeoDataRoot(),'shadow-ceo-request-owners.json'),
  captureRedis:()=>captureRedisSnapshot(queue),captureRedisIdentity:async()=>{
   const client=await queue.queue.client as unknown as Redis;
   const identity=await redisIdentity(client);
   const ownerKey=queue.queue.toKey('capture-owner'),owner=await client.get(ownerKey);
   if(!owner||!await queue.queue.isPaused())throw new Error('REDIS_CAPTURE_OWNER_REQUIRED');
   return {...identity,ownerKey,owner,metaKey:queue.queue.toKey('meta')};
  }});
}
export function verifyWork8RecoveryInventory(result:Work8RecoveryResult){return (require('../../../deployment/work8-recovery-set.cjs') as RecoveryAdapter).verifyRuntimeRecoverySet(result);}
export function invalidateWork8RecoveryInventory(destination:string){fs.rmSync(path.join(destination,'runtime-recovery.json'),{force:true});}

export function finalizeWork8RecoveryInventory(result:Work8RecoveryResult){return (require('../../../deployment/work8-recovery-set.cjs') as RecoveryAdapter).finalizeRuntimeRecoverySet(result);}


async function redisIdentity(client:Redis){
 const runId=(await client.info('server')).match(/^run_id:([a-f0-9]{40})\r?$/m)?.[1];
 const db=Number(String(await client.call('CLIENT','INFO')).match(/(?:^| )db=(\d+)(?: |$)/)?.[1]);
 if(!runId||!Number.isSafeInteger(db)||db<0)throw new Error('REDIS_IDENTITY_UNAVAILABLE');
 return {runId,db};
}

/** Inspection staging only. Never resumes BullMQ or clears producer admission.
 * Source shutdown/quarantine is an operator precondition, not established here.
 * This API cannot authorize operational restoration or global writer exclusion.
 */
export async function restoreWork8RedisInspection(request:{directory:string;digest:string;mode?:'inspection-only';expectedCaptureOwner:string;expectedSource?:{runId:string;db:number};expectedTarget?:{runId:string;db:number}},target:Redis){
 if(request.mode!=='inspection-only')throw new Error('INSPECTION_ONLY_EXPLICIT_MODE_REQUIRED');
 if(!['127.0.0.1','::1'].includes(target.options.host??'')||target.options.path)throw new Error('ISOLATED_LOOPBACK_TARGET_REQUIRED');
 const manifest=(require('../../../deployment/work8-recovery-set.cjs') as RecoveryAdapter).verifyRuntimeRecoverySet(request) as {redisDigest:string;redisCapturedAt?:number;redisIdentity?:{runId:string;db:number;ownerKey:string;owner:string;metaKey:string}};
 const source=manifest.redisIdentity;
 if(!Number.isSafeInteger(manifest.redisCapturedAt)||manifest.redisCapturedAt!<=0||manifest.redisCapturedAt!>Date.now())throw new Error('REDIS_CAPTURE_TIME_REQUIRED');
 if(!source||!/^[a-f0-9]{40}$/.test(source.runId)||!Number.isSafeInteger(source.db)||!source.ownerKey||!source.metaKey||!source.owner)throw new Error('CAPTURE_REDIS_IDENTITY_REQUIRED');
 if(request.expectedCaptureOwner!==source.owner)throw new Error('STALE_CAPTURE_OWNER');
 const observed=await redisIdentity(target);
 if(observed.runId===source.runId&&observed.db===source.db)throw new Error('SOURCE_TARGET_REDIS_ALIAS');
 // A pinned source identity authenticates lineage without requiring the source
 // process to survive. The caller separately pins the replacement endpoint.
 if(request.expectedSource&&(request.expectedSource.runId!==source.runId||request.expectedSource.db!==source.db))throw new Error('SOURCE_REDIS_IDENTITY_CHANGED');
 if(observed.runId!==source.runId&&!request.expectedSource)throw new Error('SOURCE_REDIS_IDENTITY_CHANGED');
 if(observed.runId!==source.runId&&!request.expectedTarget)throw new Error('REPLACEMENT_TARGET_IDENTITY_REQUIRED');
 if(request.expectedTarget&&(request.expectedTarget.runId!==observed.runId||request.expectedTarget.db!==observed.db))throw new Error('TARGET_REDIS_IDENTITY_CHANGED');
 const bytes=fs.readFileSync(path.join(request.directory,'redis.json'));
 if(createHash('sha256').update(bytes).digest('hex')!==manifest.redisDigest)throw new Error('REDIS_INVENTORY_CHANGED');
 const rows=JSON.parse(bytes.toString()) as Array<{key:string;dump:string;ttl:number}>;
 const owner=rows.find(row=>Buffer.from(row.key,'base64').equals(Buffer.from(source.ownerKey)));
 const meta=rows.find(row=>Buffer.from(row.key,'base64').equals(Buffer.from(source.metaKey)));
 if(!owner||owner.ttl!==-1||!meta||meta.ttl!==-1)throw new Error('PERSISTENT_CAPTURE_FENCE_REQUIRED');
 const inspectionOwner=JSON.stringify({mode:'inspection-only',captureDigest:request.digest,noExecutionAuthority:true});
 // Lua is atomic against competing clients. Errors do not roll back Redis writes:
 // keep a persistent admission owner BEFORE any subsequent row can fail.
 const script=`
 local runId=string.match(redis.call('INFO','server'),'run_id:([a-f0-9]+)')
 if runId ~= ARGV[1] then return redis.error_reply('TARGET_REDIS_IDENTITY_CHANGED') end
 redis.call('SELECT',tonumber(ARGV[2]))
 table.remove(ARGV,1); table.remove(ARGV,1)
 if redis.call('DBSIZE') ~= 0 then return redis.error_reply('INSPECTION_TARGET_NOT_EMPTY') end
 redis.call('SET',KEYS[1],ARGV[1])
 local restored=redis.pcall('RESTORE',KEYS[1],0,ARGV[2],'REPLACE')
 if type(restored)=='table' and restored.err then redis.call('SET',KEYS[1],ARGV[1]); return redis.error_reply('OWNER_DUMP_INVALID') end
 local matches=redis.call('GET',KEYS[1])==ARGV[3]
 redis.call('SET',KEYS[1],ARGV[1])
 if not matches then return redis.error_reply('CAPTURE_OWNER_MISMATCH') end
 redis.call('RESTORE',KEYS[2],0,ARGV[4])
 if redis.call('HGET',KEYS[2],'paused') ~= '1' then return redis.error_reply('CAPTURE_PAUSE_REQUIRED') end
 local clock=redis.call('TIME'); local now=tonumber(clock[1])*1000+math.floor(tonumber(clock[2])/1000)
 for i=5,#ARGV,3 do
  local expiry=tonumber(ARGV[i+1])
  if expiry==0 or expiry>now then redis.call('RESTORE',ARGV[i],expiry,ARGV[i+2],'ABSTTL') end
 end
 return 1`;
 const args:Array<string|number|Buffer>=[observed.runId,observed.db,inspectionOwner,Buffer.from(owner.dump,'base64'),source.owner,Buffer.from(meta.dump,'base64')];
 for(const row of rows)if(row!==owner&&row!==meta)args.push(Buffer.from(row.key,'base64'),row.ttl===-1?0:manifest.redisCapturedAt!+row.ttl,Buffer.from(row.dump,'base64'));
 await target.eval(script,2,source.ownerKey,source.metaKey,...args);
 return {mode:'inspection-only' as const,digest:request.digest,source, target:observed,owner:inspectionOwner,bootAllowed:false as const,noExecutionAuthority:true as const};
}

import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
// Only the actual persistence/session adapters are loaded: no host, model, Redis or live authority.
test('A8 original product-bound transcript survives writer exit and two independent cold readers',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'a8-cold-history-'));
 try{
  const context={reference:{kind:'SOURCE_DOSSIER',candidateId:'original',contextDigest:'a'.repeat(64)},label:'Historical product',productId:'product-original',variantId:'variant-original',sku:'SKU-original',phase:'DEFERRED',classification:'SOURCE_DOSSIER',sourceClassification:'REAL_READ_ONLY',source:'VERIFIED_SOURCE_DOSSIER',grantsAuthority:false,rule:'Synthetic retained-context persistence examination only',qualification:{owner:'original-owner',workspace:'workspace',supplier:{stock:null,freight:{amount:null}},sources:[{id:'original',version:1}]}};
  const turns=[{role:'user',content:'Explain this exact retained variant',timestamp:'2026-10-18T00:00:00.000Z',requestId:'original-request',productContext:context},{role:'assistant',content:'Fixture response: stock and freight remain unknown; no inference occurred.',timestamp:'2026-10-18T00:00:01.000Z',requestId:'original-request'}];
  fs.writeFileSync(path.join(root,'input.json'),JSON.stringify(turns));
  const script=`import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {ReasoningState} from ${JSON.stringify(new URL('../../orchestration/pillow-host/reasoning-state.ts',import.meta.url).href)};
import {PillowSessionStore} from ${JSON.stringify(new URL('../../orchestration/pillow-host/session-store.ts',import.meta.url).href)};
const [mode,root]=process.argv.slice(2),file=path.join(root,'reasoning.sqlite'),store=new PillowSessionStore(()=>new ReasoningState(file)),workspace='workspace:original-owner',expected=JSON.parse(fs.readFileSync(path.join(root,'input.json'),'utf8'));
if(mode==='write'){const {session}=store.getOrCreate(workspace);session.conversationHistory=expected;store.persist(session);fs.writeFileSync(path.join(root,'identity.json'),JSON.stringify({workspace,sessionId:session.sessionId}));console.log(JSON.stringify({phase:mode,pid:process.pid,sessionId:session.sessionId}));}
else{const identity=JSON.parse(fs.readFileSync(path.join(root,'identity.json'),'utf8')),session=store.get(identity.workspace,identity.sessionId);assert.ok(session);assert.equal(session.sessionId,identity.sessionId);assert.deepEqual(session.conversationHistory,expected);assert.equal(session.approvalState,'none');assert.equal(session.currentMission,null);assert.equal(store.get('workspace:foreign-owner',identity.sessionId),null);assert.equal(store.get('foreign-workspace:original-owner',identity.sessionId),null);assert.equal(store.getOrCreate(identity.workspace).session.sessionId,identity.sessionId);console.log(JSON.stringify({phase:mode,pid:process.pid,sessionId:session.sessionId,turns:session.conversationHistory,approvalState:session.approvalState,currentMission:session.currentMission}));}`;
  const child=path.join(root,'child.mjs');fs.writeFileSync(child,script);
  const run=(phase:string)=>{const result=spawnSync(process.execPath,['--import',new URL('../../../node_modules/tsx/dist/loader.mjs',import.meta.url).pathname,child,phase,root],{encoding:'utf8',timeout:15000,env:{PATH:process.env.PATH}});assert.ifError(result.error);assert.equal(result.signal,null);assert.equal(result.status,0,result.stderr);return JSON.parse(result.stdout.trim());};
  // spawnSync returns only after the writer terminates; readers cannot reuse its process state.
  const writer=run('write'),first=run('read'),second=run('read-again');assert.equal(new Set([writer.pid,first.pid,second.pid]).size,3);assert.equal(first.sessionId,writer.sessionId);assert.equal(second.sessionId,writer.sessionId);assert.deepEqual(first.turns,turns);assert.deepEqual(second.turns,turns);
  const receipt={status:'PASS_SCOPED_COLD_PROCESS_TRANSCRIPT',writerPid:writer.pid,readerPids:[first.pid,second.pid],sessionId:writer.sessionId,turnsSha256:createHash('sha256').update(JSON.stringify(turns)).digest('hex'),paidInference:0,externalEffects:0,scope:'Actual ReasoningState and PillowSessionStore only. Writer terminated before independent cold readers; canonical identity, full product/source/version/unknown fields and owner/workspace isolation preserved. No HTTP authentication, Redis or full application restoration claim.'};
  console.log(JSON.stringify(receipt));
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});

import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {randomUUID} from 'node:crypto';
import {createRequire} from 'node:module';
import {DatabaseSync} from 'node:sqlite';
import {withExclusiveWork8DomainCapture} from '../../runtime/native-store-capture.js';
const require=createRequire(import.meta.url);
const vault=require('../../../../deployment/work8-system-vault.cjs');
const recovery=require('../../../../deployment/work8-recovery-set.cjs');
function fixture(){
 const base=fs.mkdtempSync(path.join(os.tmpdir(),'runtime-recovery-')),root=path.join(base,'volume');fs.mkdirSync(root);
 const primaryPath=path.join(root,'brain.db'),shadowPath=path.join(root,'shadow.db');
 const files=[...Object.values(vault.STORES) as string[]].map(x=>path.join(root,x)).concat([primaryPath,primaryPath+'.missions.sqlite',primaryPath+'.mission-execution.sqlite',shadowPath]);
 const handles:DatabaseSync[]=[];
 for(const [i,file] of files.entries()){fs.mkdirSync(path.dirname(file),{recursive:true});const db=new DatabaseSync(file);db.exec(`PRAGMA journal_mode=${i%2?'DELETE':'WAL'};CREATE TABLE canonical(id TEXT PRIMARY KEY,value INTEGER);INSERT INTO canonical VALUES('retained',${i});`);handles.push(db);}
 const authorityFile=path.join(root,'authority.json'),requestOwnersFile=path.join(root,'owners.json');fs.writeFileSync(authorityFile,JSON.stringify({approvals:['historical']}));fs.writeFileSync(requestOwnersFile,'{}');
 return {base,root,files,args:{root,primaryPath,shadowPath,authorityFile,requestOwnersFile,destination:path.join(base,'capture'),sourceCommit:'a'.repeat(40),frontendRevision:'b'.repeat(40),captureId:randomUUID(),captureRedis:async()=>[{key:'a2V5',dump:'ZHVtcA==',ttl:-1}]},close(){for(const db of handles)db.close();fs.rmSync(base,{recursive:true,force:true});}};
}
test('integrated inventory retains all thirteen stores including WAL records, stages empty isolated inspection, rejects tampering',async()=>{
 const f=fixture();try{
  const captured=await withExclusiveWork8DomainCapture(f.root,()=>recovery.captureRuntimeRecoverySet(f.args));
  assert.equal(fs.existsSync(path.join(captured.directory,'runtime-recovery.json')),false);
  assert.throws(()=>recovery.verifyRuntimeRecoverySet(captured),/ENOENT/);
  assert.throws(()=>recovery.stageRuntimeRecoveryInspection({...captured,destination:path.join(f.base,'premature')}),/ENOENT/);
  recovery.finalizeRuntimeRecoverySet(captured);
  const m=recovery.verifyRuntimeRecoverySet(captured);assert.equal(Object.keys(m.stores).length,13);assert.ok(m.stores.liveCostCentre);assert.ok(m.stores.execution);assert.equal(m.completeLiveState,false);assert.equal(m.bootAllowed,false);
  const staged=recovery.stageRuntimeRecoveryInspection({...captured,destination:path.join(f.base,'inspection')});assert.equal(staged.bootAllowed,false);
  for(const id of Object.keys(m.stores)){const db=new DatabaseSync(path.join(staged.directory,'sealed-evidence',id,'checkpoint.db'),{readOnly:true});try{assert.equal(db.prepare('SELECT count(*) AS n FROM canonical').get()!.n,1);}finally{db.close();}}
  assert.throws(()=>recovery.stageRuntimeRecoveryInspection({...captured,destination:staged.directory}),/EEXIST/);
  fs.appendFileSync(path.join(captured.directory,'redis.json'),' ');assert.throws(()=>recovery.verifyRuntimeRecoverySet(captured));
 }finally{f.close();}
});
test('missing mandatory financial or mission store refuses before destination is created',async()=>{
 for(const suffix of ['commissioning/openai-october-2026.sqlite','brain.db.mission-execution.sqlite']){const f=fixture();try{fs.renameSync(path.join(f.root,suffix),path.join(f.root,suffix)+'.absent');await assert.rejects(recovery.captureRuntimeRecoverySet(f.args),/ENOENT/);assert.equal(fs.existsSync(f.args.destination),false);}finally{f.close();}}
});
test('Redis interruption after SQLite copies cannot leave a success manifest',async()=>{
 const f=fixture();try{await assert.rejects(withExclusiveWork8DomainCapture(f.root,()=>recovery.captureRuntimeRecoverySet({...f.args,captureRedis:async()=>{throw new Error('Redis interrupted');}})),/Redis interrupted/);assert.equal(fs.existsSync(path.join(f.args.destination,'runtime-recovery.json')),false);}finally{f.close();}
});

test('complete runtime capture defaults to refusal instead of accepting a scoped inventory',async()=>{
 const {captureWork8RecoveryInventory}=await import('../../runtime/work8-recovery-capture.js');
 const f=fixture();try{
  for(const requireComplete of [undefined,true])await assert.rejects(captureWork8RecoveryInventory({...f.args,requireComplete},{root:f.root,primaryPath:f.args.primaryPath,shadowPath:f.args.shadowPath},undefined as never),/FULL_RUNTIME_CAPTURE_UNPROVEN/);
  assert.equal(fs.existsSync(f.args.destination),false);
 }finally{f.close();}
});

test('supervised observer sidecar is mandatory, bounded, independently hashed, and remains historical',async()=>{
 const f=fixture();try{
  const args={...f.args,captureObserverWatchdog:true};
  await assert.rejects(recovery.captureRuntimeRecoverySet(args),/ENOENT/);assert.equal(fs.existsSync(args.destination),false);
  const file=path.join(f.root,'commissioning/assurance.sqlite.watchdog');
  fs.writeFileSync(file+'.tmp','{}');await assert.rejects(recovery.captureRuntimeRecoverySet(args),/OBSERVER_WATCHDOG_UNSETTLED/);fs.rmSync(file+'.tmp');
  fs.symlinkSync(f.args.authorityFile,file);await assert.rejects(recovery.captureRuntimeRecoverySet(args));fs.rmSync(file);
  fs.writeFileSync(file,'x'.repeat(65537));
  await assert.rejects(recovery.captureRuntimeRecoverySet(args),/OBSERVER_WATCHDOG_SIZE/);assert.equal(fs.existsSync(path.join(args.destination,'runtime-recovery.json')),false);fs.rmSync(args.destination,{recursive:true,force:true});
  fs.writeFileSync(file,JSON.stringify({observedAt:Date.now(),status:'NOT_CHECKED'}));
  const result=await withExclusiveWork8DomainCapture(f.root,()=>recovery.captureRuntimeRecoverySet(args));recovery.finalizeRuntimeRecoverySet(result);
  const manifest=recovery.verifyRuntimeRecoverySet(result);assert.equal(Object.keys(manifest.stores).length,13);assert.equal(manifest.bootAllowed,false);assert.ok(manifest.json.assuranceWatchdog);
  fs.appendFileSync(path.join(result.directory,'assuranceWatchdog.json'),' ');assert.throws(()=>recovery.verifyRuntimeRecoverySet(result));
 }finally{f.close();}
});

test('Redis snapshot time uses the atomic server clock and preserves the row-array API',async()=>{
 const {captureRedisSnapshot,captureRedisInventory}=await import('../../runtime/work8-recovery-capture.js');
 const serverTime=1_800_000_005_000;
 const binaryKey=Buffer.from([0,255,17]),dump=Buffer.from([255,0,123]);
 const queue={queue:{client:Promise.resolve({evalBuffer:async(script:string)=>{
  assert.match(script,/redis.call\('TIME'\)/);
  assert.match(script,/return \{capturedAt, out\}/);
  return [serverTime,[[binaryKey,dump,60000]]];
 }})}};
 const timed=await captureRedisSnapshot(queue as never);
 assert.equal(timed.capturedAt,serverTime);
 assert.deepEqual(timed.rows,[{key:binaryKey.toString('base64'),dump:dump.toString('base64'),ttl:60000}]);
 assert.deepEqual(await captureRedisInventory(queue as never),timed.rows);
 for(const invalid of [0,-1,NaN,1.5,Number.MAX_SAFE_INTEGER+1]){
  const bad={queue:{client:Promise.resolve({evalBuffer:async()=>[invalid,[]]})}};
  await assert.rejects(captureRedisSnapshot(bad as never),/REDIS_SNAPSHOT_TIME_INVALID/);
 }
});

test('Redis snapshot time survives client dispatch delay in the durable recovery manifest',async()=>{
 const f=fixture();try{
  const before=Date.now(),serverSnapshotTime=before+5000;
  const rows=[{key:'c2Vzc2lvbg==',dump:'ZHVtcA==',ttl:60000}];
  // Model five seconds between invocation and execution without sleeping.
  const captured=await withExclusiveWork8DomainCapture(f.root,()=>recovery.captureRuntimeRecoverySet({
   ...f.args,captureRedis:async()=>({capturedAt:serverSnapshotTime,rows})
  }));
  recovery.finalizeRuntimeRecoverySet(captured);
  const m=recovery.verifyRuntimeRecoverySet(captured);
  assert.equal(m.redisCapturedAt,serverSnapshotTime);
  assert.equal(m.redisCapturedAt+rows[0]!.ttl,serverSnapshotTime+60000);
  assert.notEqual(m.redisCapturedAt,before);
  assert.deepEqual(JSON.parse(fs.readFileSync(path.join(captured.directory,'redis.json'),'utf8')),rows);
  assert.equal(m.bootAllowed,false);assert.equal(m.completeLiveState,false);
 }finally{f.close();}
});

test('Redis snapshot time keeps legacy array callbacks compatible and rejects invalid clock before sealing',async()=>{
 const f=fixture();try{
  const before=Date.now();
  const captured=await withExclusiveWork8DomainCapture(f.root,()=>recovery.captureRuntimeRecoverySet(f.args));
  recovery.finalizeRuntimeRecoverySet(captured);
  const m=recovery.verifyRuntimeRecoverySet(captured);
  assert.ok(m.redisCapturedAt>=before&&m.redisCapturedAt<=Date.now());
 }finally{f.close();}
 const bad=fixture();try{
  await assert.rejects(withExclusiveWork8DomainCapture(bad.root,()=>recovery.captureRuntimeRecoverySet({
   ...bad.args,captureRedis:async()=>({capturedAt:NaN,rows:[]})
  })),/REDIS_SNAPSHOT_TIME_INVALID/);
  assert.equal(fs.existsSync(path.join(bad.args.destination,'runtime-recovery.pending.json')),false);
  assert.equal(fs.existsSync(path.join(bad.args.destination,'runtime-recovery.json')),false);
 }finally{bad.close();}
});

'use strict';
// Composition of existing verifiers; no runtime boot, authority import or source writes.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');const {DatabaseSync}=require('node:sqlite');
const {verifySystem,selectSystemPoint}=require('./work8-system-vault.cjs');
const {verifyCheckpoint}=require('./legacy-checkpoint-capture.cjs');
const {verifyLegacyShadowDisk}=require('./legacy-shadow-state-capture.cjs');
const {MARKERS,captureLifecycleMarkers,verifyLifecycleMarkers}=require('./work8-lifecycle-markers.cjs');
const names=['system','brain','missions','execution','shadow'];
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function canonical(p){assert.ok(path.isAbsolute(p));assert.equal(fs.realpathSync(p),p);}
